def load_delta() -> list[tuple[int, bytes]]:
    """Return [(fw_all offset, replacement bytes), ...]."""
    raw = lzma.decompress(base64.b64decode(_DELTA_B64))
    output: list[tuple[int, bytes]] = []
    cursor = 0
    while cursor < len(raw):
        offset, length = struct.unpack_from("<II", raw, cursor)
        cursor += 8
        output.append((offset, raw[cursor : cursor + length]))
        cursor += length
    if cursor != len(raw) or len(output) != DELTA_SPAN_COUNT:
        raise ValueError("delta record stream mismatch")
    return output
